1.3.6
type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

function fail(message: string): never {
  console.error(`Error: ${message}`);
  process.exit(1);
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseInput(value: unknown): Task[] {
  if (!isObject(value) || !Array.isArray(value.tasks)) {
    fail("input must be an object with a tasks array");
  }

  const tasks: Task[] = [];
  const ids = new Set<string>();
  for (let index = 0; index < value.tasks.length; index += 1) {
    const raw = value.tasks[index];
    if (!isObject(raw)) fail(`tasks[${index}] must be an object`);
    if (typeof raw.id !== "string" || raw.id.length === 0) {
      fail(`tasks[${index}].id must be a non-empty string`);
    }
    if (ids.has(raw.id)) fail(`duplicate task id: ${raw.id}`);
    if (typeof raw.duration !== "number" || !Number.isFinite(raw.duration) || raw.duration < 0) {
      fail(`tasks[${index}].duration must be a finite non-negative number`);
    }
    const dependencies = raw.dependsOn === undefined ? [] : raw.dependsOn;
    if (!Array.isArray(dependencies) || dependencies.some((item) => typeof item !== "string")) {
      fail(`tasks[${index}].dependsOn must be an array of strings`);
    }
    const seen = new Set<string>();
    for (const dependency of dependencies) {
      if (seen.has(dependency)) fail(`task ${raw.id} has duplicate dependency: ${dependency}`);
      if (dependency === raw.id) fail(`task ${raw.id} cannot depend on itself`);
      seen.add(dependency);
    }
    ids.add(raw.id);
    tasks.push({ id: raw.id, duration: raw.duration, dependsOn: [...dependencies] });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) fail(`task ${task.id} depends on unknown task: ${dependency}`);
    }
  }
  return tasks;
}

function compareIds(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function compareSequences(a: string[], b: string[]): number {
  const length = Math.min(a.length, b.length);
  for (let index = 0; index < length; index += 1) {
    const comparison = compareIds(a[index], b[index]);
    if (comparison !== 0) return comparison;
  }
  return a.length - b.length;
}

function findCycle(tasks: Task[], graph: Map<string, string[]>): string[] | undefined {
  const state = new Map<string, number>();
  const stack: string[] = [];
  const position = new Map<string, number>();

  function visit(id: string): string[] | undefined {
    state.set(id, 1);
    position.set(id, stack.length);
    stack.push(id);
    for (const next of graph.get(id) ?? []) {
      if (state.get(next) === 1) {
        return [...stack.slice(position.get(next)), next];
      }
      if (!state.get(next)) {
        const cycle = visit(next);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    position.delete(id);
    state.set(id, 2);
    return undefined;
  }

  for (const task of [...tasks].sort((a, b) => compareIds(a.id, b.id))) {
    if (!state.get(task.id)) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

function makePlan(tasks: Task[]): Plan {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const graph = new Map<string, string[]>();
  const indegree = new Map<string, number>();
  for (const task of tasks) {
    graph.set(task.id, []);
    indegree.set(task.id, task.dependsOn.length);
  }
  for (const task of tasks) {
    for (const dependency of task.dependsOn) graph.get(dependency)!.push(task.id);
  }
  for (const successors of graph.values()) successors.sort(compareIds);

  const ready = tasks.filter((task) => indegree.get(task.id) === 0).map((task) => task.id).sort(compareIds);
  const order: string[] = [];
  const layers: string[][] = [];
  const earliest: Record<string, { start: number; finish: number }> = {};
  const paths = new Map<string, string[]>();

  while (ready.length > 0) {
    const layer = ready.splice(0).sort(compareIds);
    layers.push(layer);
    for (const id of layer) {
      order.push(id);
      const task = byId.get(id)!;
      let start = 0;
      let bestPath: string[] = [id];
      for (const dependency of task.dependsOn) {
        const dependencyFinish = earliest[dependency].finish;
        if (dependencyFinish > start) {
          start = dependencyFinish;
          bestPath = [...paths.get(dependency)!, id];
        } else if (dependencyFinish === start) {
          const candidate = [...paths.get(dependency)!, id];
          if (compareSequences(candidate, bestPath) < 0) bestPath = candidate;
        }
      }
      earliest[id] = { start, finish: start + task.duration };
      paths.set(id, bestPath);
      for (const successor of graph.get(id)!) {
        indegree.set(successor, indegree.get(successor)! - 1);
        if (indegree.get(successor) === 0) ready.push(successor);
      }
    }
  }

  if (order.length !== tasks.length) {
    const cycle = findCycle(tasks, graph);
    fail(`dependency cycle: ${(cycle ?? []).join(" -> ")}`);
  }

  let totalDuration = 0;
  let criticalPath: string[] = [];
  for (const id of order) {
    const finish = earliest[id].finish;
    if (finish > totalDuration || (finish === totalDuration && compareSequences(paths.get(id)!, criticalPath) < 0)) {
      totalDuration = finish;
      criticalPath = paths.get(id)!;
    }
  }
  return { order, layers, earliest, totalDuration, criticalPath };
}

function main(): void {
  const args = Bun.argv.slice(2);
  if (args.length !== 2 || args[0] !== "plan" || args[1].startsWith("-")) {
    fail("usage: bun run src/cli.ts plan INPUT.json");
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(require("fs").readFileSync(args[1], "utf8"));
  } catch (error) {
    fail(`cannot read or parse input JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  console.log(JSON.stringify(makePlan(parseInput(parsed))));
}

main();

